using System.ComponentModel;
using ModelContextProtocol.Server;

[McpServerToolType]
public static class ConfigTools
{
    [McpServerTool, Description("Validates a configuration key and returns whether it exists with its current value.")]
    public static string ValidateConfig(
        [Description("The configuration key to validate (e.g., 'MaxRetries', 'TimeoutSeconds')")] string key)
    {
        var knownKeys = new Dictionary<string, string>
        {
            ["MaxRetries"] = "3",
            ["TimeoutSeconds"] = "30",
            ["Version"] = "1.0.0"
        };

        return knownKeys.TryGetValue(key, out var value)
            ? $"✓ '{key}' exists with value: {value}"
            : $"✗ '{key}' is not a recognized configuration key.";
    }
}

